syntax:
template<typename T>
class auto_ptr {
public:
    explicit auto_ptr(T* p = nullptr); // Constructor
    auto_ptr(const auto_ptr& other); // Copy constructor (transfers ownership)
    auto_ptr& operator=(auto_ptr& other); // Assignment operator (transfers ownership)
    ~auto_ptr(); // Destructor
    T* release(); // Releases ownership
    T* get() const; // Access raw pointer
    void reset(T* p = nullptr); // Replace managed object
private:
    T* ptr;
};

code_example:
#include <memory>
class ClassA {
public:
    void doSomething() {}
};
int main() {
    std::auto_ptr<ClassA> ptr1(new ClassA);
    std::auto_ptr<ClassA> ptr2(new ClassA);
    ptr2 = ptr1; // Transfer ownership from ptr1 to ptr2
    // At this point, ptr1 is null, and ptr2 owns the object
    if (ptr1.get() == nullptr) {
        // ptr1 no longer owns the object
    }
    if (ptr2.get() != nullptr) {
        ptr2->doSomething();
    }
    return 0;
}
